<?php $root_dir="/data/data/com.termux/files/home/apache/files";$message="";$message_type="";$compiled_url="";function renderXploreTree($dir,$root_base){$ffs=scandir($dir);unset($ffs[array_search('.',$ffs,true)],$ffs[array_search('..',$ffs,true)]);if(count($ffs)<1)return;$style=($dir===$root_base)?'':'style="display:none;"';echo '<ul '.$style.'>';foreach($ffs as $ff){if($ff==='.'||$ff==='cache'||$ff==='vendor'||$ff==='node_modules'||strpos($ff,'.')===0)continue;$current_path=$dir.'/'.$ff;$relative_path=str_replace($root_base.'/','',$current_path);if(is_dir($current_path)){echo '<li class="folder-node"><span class="folder-toggle"><span class="arrow-icon">▶</span><svg class="md2-inline-svg folder-color" viewBox="0 0 24 24"><path d="M10 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2h-8l-2-2z"/></svg><span>'.htmlspecialchars($ff).'</span></span>';renderXploreTree($current_path,$root_base);echo '</li>';}else{$ext=pathinfo($ff,PATHINFO_EXTENSION);if($ext==='txt'){echo '<li class="file-node"><form method="POST" action="" style="display:inline;"><input type="hidden" name="target_file_path" value="'.htmlspecialchars($relative_path).'"><svg class="md2-inline-svg file-color" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg><button type="submit" name="compile_tree_file" class="tree-compile-btn">'.htmlspecialchars($ff).'</button></form></li>';}}}echo '</ul>';}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['compile_tree_file'])){$safe_relative=str_replace(['../','..\\'],'',$_POST['target_file_path']);$file_path=$root_dir.'/'.$safe_relative;if(file_exists($file_path)&&pathinfo($file_path,PATHINFO_EXTENSION)==='txt'){$filename=pathinfo($file_path,PATHINFO_FILENAME);$file_dir=pathinfo($file_path,PATHINFO_DIRNAME);$output_file=$file_dir.'/'.$filename.'.html';$txt_content=file_get_contents($file_path);$safe_content=htmlspecialchars($txt_content,ENT_QUOTES,'UTF-8');$lines=explode("\n",$safe_content);$html_paragraphs="";foreach($lines as $line){if(trim($line)!==""){$html_paragraphs.="        <p>".trim($line)."</p>\n";}}$html_template="<!DOCTYPE html><html lang='ru'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1.0'><title>".htmlspecialchars($filename)."</title><style>body{background:#ffffff;color:#1f2328;font-family:-apple-system,BlinkMacSystemFont,arial;line-height:1.6;margin:0;padding:30px;display:flex;justify-content:center;}.content-box{width:100%;max-width:800px;border:1px solid #d0d7de;background:#f6f8fa;padding:40px;border-radius:6px;box-shadow:0 2px 8px rgba(0,0,0,0.05);box-sizing:border-box;}h1{font-size:26px;border-bottom:1px solid #d0d7de;padding-bottom:10px;margin-top:0;color:#0969da;}p{font-size:16px;margin:12px 0;white-space:pre-wrap;}</style></head><body><div class='content-box'><h1>".htmlspecialchars($filename)."</h1>\n".$html_paragraphs."    </div></body></html>";if(file_put_contents($output_file,$html_template)!==false){chmod($output_file,0777);$message="Done! File converted to html.";$message_type="success";$web_link=str_replace($root_dir,'',$output_file);$compiled_url=ltrim($web_link,'/');}else{$message="Critical error.";$message_type="error";}}else{$message="Error: File not found or not secure.";$message_type="error";}}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no"><title>Compiler</title><style>html,body{background:#ffffff;color:#1f2328;font-family:Arial,-apple-system,sans-serif!important;margin:0!important;padding:0!important;width:100vw;height:100vh;overflow:hidden;box-sizing:border-box;}.compiler-panel{width:100vw;height:100vh;background:#f6f8fa;margin:0!important;padding:20px!important;box-sizing:border-box;display:flex;flex-direction:column;}h2{margin-top:0;font-size:22px;color:#0969da;border-bottom:1px solid #d0d7de;padding-bottom:10px;font-weight:bold;margin-bottom:5px;flex-shrink:0;display:flex;align-items:center;gap:8px;}.instruction-text{font-size:13px;color:#57606a;margin-top:5px;margin-bottom:15px;line-height:1.4;flex-shrink:0;}.tree-container{background:#ffffff;border:1px solid #d0d7de;border-radius:6px;padding:20px;overflow-y:auto;box-sizing:border-box;flex-grow:1;}ul{list-style-type:none;padding-left:18px;margin:4px 0;}li{margin:6px 0;font-size:16px;position:relative;}.folder-node{color:#24292f;}.md2-inline-svg{width:22px;height:22px;vertical-align:middle;display:inline-block;margin-right:4px;flex-shrink:0;}.folder-color{fill:#0969da;}.file-color{fill:#57606a;}.root-color{fill:#1f2328;}.arrow-icon{font-size:11px;color:#8c959f;display:inline-block;width:12px;transition:transform 0.1s;}.folder-node.expanded > .folder-toggle .arrow-icon{transform:rotate(90deg);color:#0969da;}.folder-toggle{cursor:pointer;font-weight:bold;padding:4px 6px;border-radius:4px;display:inline-flex;align-items:center;transition:0.1s;gap:2px;}.folder-toggle:hover{background:#eaeef2;color:#0969da;}.folder-node.expanded > .folder-toggle{color:#0969da;}.file-node{padding-left:14px;display:flex;align-items:center;}.tree-compile-btn{background:none;border:none;color:#0969da;font-family:Arial,sans-serif!important;font-size:15px;cursor:pointer;padding:2px 6px;border-radius:4px;font-weight:bold;text-align:left;}.tree-compile-btn:hover{background:#dafbe1;color:#1a7f37;text-decoration:underline;}.alert{padding:12px 15px;border-radius:6px;margin-bottom:15px;font-size:14px;font-weight:bold;flex-shrink:0;}.alert-success{background:#dafbe1;color:#1a7f37;border:1px solid #a2f5ba;}.alert-error{background:#ffebe9;color:#cf222e;border:1px solid #ffc5c2;}.link-box{margin-bottom:15px;background:#ffffff;border:1px solid #dafbe1;padding:15px;border-radius:6px;text-align:center;font-size:16px;box-shadow:0 2px 6px rgba(26,127,55,0.02);flex-shrink:0;}.link-box a{color:#1a7f37;text-decoration:none;font-weight:bold;border-bottom:2px solid #a2f5ba;padding:2px 4px;}.link-box a:hover{color:#115e29;background:#dafbe1;border-radius:4px;}@media(max-width:768px){.compiler-panel{padding:12px!important;}h2{font-size:18px;}.tree-container{padding:10px;}ul{padding-left:12px;}li{font-size:14px;}.md2-inline-svg{width:18px;height:18px;}}</style></head><body><div class="compiler-panel"><h2><svg class="md2-inline-svg folder-color" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg><span>TXT to HTML</span></h2><p class="instruction-text">TXT to HTML Converter. Tap on folders to open them. Find any txt file and press on it to convert it to html.</p><?php if($message):?><div class="alert alert-<?php echo $message_type;?>"><?php echo $message;?></div><?php endif;?><?php if($compiled_url):?><div class="link-box"><a href="/<?php echo htmlspecialchars($compiled_url);?>" target="_blank">Open converted page</a></div><?php endif;?><div class="tree-container"><div class="folder-node expanded" style="margin-bottom:5px;"><svg class="md2-inline-svg root-color" viewBox="0 0 24 24"><path d="M2 20h20v-4H2v4zm2-3h2v2H4v-2zM2 4v4h20V4H2zm4 3H4V5h2v2zm-4 7h20v-4H2v4zm2-3h2v2H4v-2z"/></svg><strong>root/</strong></div><?php renderXploreTree($root_dir,$root_dir);?></div></div><script>document.addEventListener("DOMContentLoaded",function(){const toggles=document.querySelectorAll(".folder-toggle");toggles.forEach(toggle=>{toggle.addEventListener("click",function(e){e.stopPropagation();const li=this.parentElement;const subUl=li.querySelector("ul");if(subUl){if(subUl.style.display==="none"){subUl.style.display="block";li.classList.add("expanded");}else{subUl.style.display="none";li.classList.remove("expanded");}}});});});</script></body></html>
